86: void BreathAlgo_Feed(float raw)
87: {
88:     float ac, k1, k2, amp_th;
89:     uint16_t i;
90:     uint32_t now;
91: 
92:     s_baseline = 0.98f * s_baseline + 0.02f * raw;
93:     ac = raw - s_baseline;
94:     s_lpf = 0.20f * s_lpf + 0.80f * ac;
95:     s_buf[s_idx++ % BREATH_BUF_LEN] = s_lpf;
96:     if (s_idx < 9) return;
97: 
98:     i = s_idx;
99:     k1 = (s_buf[(i-1)%BREATH_BUF_LEN] + s_buf[(i-2)%BREATH_BUF_LEN]
100:         - s_buf[(i-3)%BREATH_BUF_LEN] - s_buf[(i-4)%BREATH_BUF_LEN]) / 2.0f;
101:     k2 = (s_buf[(i-5)%BREATH_BUF_LEN] + s_buf[(i-6)%BREATH_BUF_LEN]
102:         - s_buf[(i-7)%BREATH_BUF_LEN] - s_buf[(i-8)%BREATH_BUF_LEN]) / 2.0f;
103: 
104:     now = GetTick();
105:     amp_th = s_valley_amp_avg * 0.4f;
106:     if (amp_th < VALLEY_AMP_THRESH) amp_th = VALLEY_AMP_THRESH;
107: 
108:     if (k1 < 0.0f && k2 > 0.0f &&
109:         (now - s_last_valley_tick) > PEAK_MIN_INTERVAL_MS &&
110:         fabsf(s_lpf) < amp_th)
111:     {
112:         s_last_valley_tick = now;
113:         s_valley_amp_avg = 0.9f * s_valley_amp_avg + 0.1f * fabsf(s_lpf);
114:         BreathAlgo_OnValley(now);
115:     }
116: }
