#include "bsp_audio.h"
#include "usart.h"
#include <string.h>

/* Set to 1 for N9300 standard 0x7E..0xEF protocol, 0 for compact 0xA0 3-byte protocol */
#ifndef AUDIO_USE_N9300_STD_FRAME
#define AUDIO_USE_N9300_STD_FRAME   1
#endif

#define AUDIO_RX_RING_SIZE  64U
#define AUDIO_FRAME_MAX_LEN 32U

static uint8_t  s_rx_ring[AUDIO_RX_RING_SIZE];
static volatile uint16_t s_rx_head = 0U;
static volatile uint16_t s_rx_tail = 0U;
static uint8_t  s_rx_byte_it = 0U;

static uint8_t  s_rx_frame[AUDIO_FRAME_MAX_LEN];
static uint8_t  s_rx_len = 0U;
static uint8_t  s_last_ack_cmd = 0U;
static uint8_t  s_online = 0U;

static void audio_send_bytes(const uint8_t *buf, uint16_t len)
{
    HAL_UART_Transmit(&huart2, (uint8_t *)buf, len, 50U);
}

#if AUDIO_USE_N9300_STD_FRAME
/* N9300 frame: [0x7E] [LEN] [CMD] [P0] [P1] [CHK] [0xEF]
 * LEN = number of bytes from LEN through CHK minus 1 (or CMD..P1 + 2), CHK = XOR of LEN..Pn
 */
static void n9300_send_cmd(uint8_t cmd, uint8_t p0, uint8_t p1, uint8_t has_2_params)
{
    uint8_t frame[8];
    uint8_t idx = 0U;
    uint8_t xor_chk = 0U;
    uint8_t i;

    frame[idx++] = 0x7EU;
    frame[idx++] = has_2_params ? 4U : 3U; /* LEN: LEN_byte + CMD + params */
    frame[idx++] = cmd;
    if (has_2_params)
    {
        frame[idx++] = p0;
        frame[idx++] = p1;
    }
    else
    {
        frame[idx++] = p0;
    }

    for (i = 1U; i < idx; i++)
    {
        xor_chk ^= frame[i];
    }
    frame[idx++] = xor_chk;
    frame[idx++] = 0xEFU;

    audio_send_bytes(frame, idx);
}
#endif

void BSP_Audio_Init(void)
{
    s_rx_head = 0U;
    s_rx_tail = 0U;
    s_rx_len = 0U;
    HAL_UART_Receive_IT(&huart2, &s_rx_byte_it, 1U);
    BSP_Audio_SetVolume(5U);
}

void BSP_Audio_OnUartRxByte(uint8_t byte)
{
    uint16_t next = (uint16_t)((s_rx_head + 1U) % AUDIO_RX_RING_SIZE);
    if (next != s_rx_tail)
    {
        s_rx_ring[s_rx_head] = byte;
        s_rx_head = next;
    }
    HAL_UART_Receive_IT(&huart2, &s_rx_byte_it, 1U);
}

void BSP_Audio_Poll(void)
{
    while (s_rx_tail != s_rx_head)
    {
        uint8_t b = s_rx_ring[s_rx_tail];
        s_rx_tail = (uint16_t)((s_rx_tail + 1U) % AUDIO_RX_RING_SIZE);

        if (s_rx_len == 0U && b != 0x7EU)
        {
            continue;
        }
        if (s_rx_len < AUDIO_FRAME_MAX_LEN)
        {
            s_rx_frame[s_rx_len++] = b;
            if (b == 0xEFU && s_rx_len >= 5U)
            {
                s_last_ack_cmd = s_rx_frame[2];
                s_online = 1U;
                s_rx_len = 0U;
            }
        }
        else
        {
            s_rx_len = 0U;
        }
    }
}

void BSP_Audio_SetVolume(uint8_t ui_vol_0_to_10)
{
    uint8_t hw_vol;
    if (ui_vol_0_to_10 > AUDIO_VOL_UI_MAX) ui_vol_0_to_10 = AUDIO_VOL_UI_MAX;
    hw_vol = (uint8_t)((uint16_t)ui_vol_0_to_10 * AUDIO_VOL_HW_MAX / AUDIO_VOL_UI_MAX);

#if AUDIO_USE_N9300_STD_FRAME
    n9300_send_cmd(0x31U, hw_vol, 0U, 0U); /* 0x31: Set volume (0~30) */
#else
    uint8_t c[3] = {0xA0U, 0x0EU, ui_vol_0_to_10};
    audio_send_bytes(c, 3U);
#endif
}

void BSP_Audio_PlayTrack(uint16_t track_id)
{
#if AUDIO_USE_N9300_STD_FRAME
    n9300_send_cmd(0x41U, (uint8_t)(track_id >> 8), (uint8_t)(track_id & 0xFFU), 1U); /* 0x41: Play track by index */
#else
    uint8_t c[3] = {0xA0U, 0x01U, (uint8_t)(track_id & 0xFFU)};
    audio_send_bytes(c, 3U);
#endif
}

void BSP_Audio_PlayVoice(AudioVoiceId_t id)
{
    BSP_Audio_PlayTrack((uint16_t)id);
}

void BSP_Audio_Stop(void)
{
#if AUDIO_USE_N9300_STD_FRAME
    n9300_send_cmd(0x0EU, 0U, 0U, 0U); /* 0x0E: Stop playback */
#else
    uint8_t c[3] = {0xA0U, 0x03U, 0x00U};
    audio_send_bytes(c, 3U);
#endif
}

void BSP_Audio_Pause(void)
{
#if AUDIO_USE_N9300_STD_FRAME
    n9300_send_cmd(0x02U, 0U, 0U, 0U); /* 0x02: Pause */
#else
    BSP_Audio_Stop();
#endif
}

uint8_t BSP_Audio_IsBusy(void)
{
    return (HAL_GPIO_ReadPin(AUDIO_BUSY_GPIO_Port, AUDIO_BUSY_Pin) == GPIO_PIN_SET) ? 1U : 0U;
}

uint8_t BSP_Audio_IsHeadphoneInserted(void)
{
    /* HP_DET (PA4) pulled up to 3.3V when inserted -> shuts down 8002A speaker amp */
    return (HAL_GPIO_ReadPin(HP_DET_GPIO_Port, HP_DET_Pin) == GPIO_PIN_SET) ? 1U : 0U;
}

void BSP_Audio_GetStatus(AudioStatus_t *out)
{
    if (out == NULL) return;
    out->busy = BSP_Audio_IsBusy();
    out->headphone_inserted = BSP_Audio_IsHeadphoneInserted();
    out->last_ack_cmd = s_last_ack_cmd;
    out->online = s_online;
}

#ifndef __BSP_BLE_H
#define __BSP_BLE_H

#include "main.h"

#ifdef __cplusplus
extern "C" {
#endif

#define BLE_FRAME_SOF0      0xAAU
#define BLE_FRAME_SOF1      0x55U
#define BLE_FRAME_EOF       0x0DU

typedef enum {
    BLE_CMD_TELEMETRY       = 0x01U,
    BLE_CMD_SET_PARAMS      = 0x10U,
    BLE_CMD_CTRL_STATE      = 0x11U,
    BLE_CMD_QUERY_STATUS    = 0x12U
} BleCmdId_t;

typedef struct {
    uint8_t  breath_mode;     /* 0:Off, 1:Simple, 2:Biofeedback */
    uint8_t  stim_mode;       /* 0:Off, 1:Continuous, 2:Intermittent, 3:Dense-Disperse */
    uint8_t  stim_freq_hz;    /* 0..100 */
    uint8_t  stim_level[3];   /* 0..10 */
    uint8_t  timer_min;       /* 5..30 */
    uint16_t elapsed_sec;
    uint16_t remain_sec;
    uint8_t  guide_bpm;       /* 5..30 */
    uint8_t  real_cbpm;       /* 0..50 */
    uint8_t  elec_drop_mask;  /* bit0:CH1, bit1:CH2, bit2:CH3 */
    uint8_t  running;
    uint8_t  paused;
} BleTelemetry_t;

typedef struct {
    uint8_t cmd_id;
    uint8_t payload[24];
    uint8_t payload_len;
} BleRxCommand_t;

typedef void (*BleRxCallback_t)(const BleRxCommand_t *cmd);

void BSP_BLE_Init(BleRxCallback_t cb);
void BSP_BLE_Reset(void);
void BSP_BLE_SetEnabled(uint8_t enable);
uint8_t BSP_BLE_IsConnected(void);

void BSP_BLE_OnUartRxByte(uint8_t byte);
void BSP_BLE_OnDataReadyExti(void);
void BSP_BLE_Poll(void);

void BSP_BLE_SendTelemetry(const BleTelemetry_t *t);

#ifdef __cplusplus
}
#endif

#endif /* __BSP_BLE_H */

#include "bsp_ble.h"
#include "usart.h"
#include <string.h>

#define BLE_RX_RING_SIZE    128U
#define BLE_FRAME_MAX_LEN   40U

static uint8_t  s_rx_ring[BLE_RX_RING_SIZE];
static volatile uint16_t s_rx_head = 0U;
static volatile uint16_t s_rx_tail = 0U;
static uint8_t  s_rx_byte_it = 0U;
static volatile uint8_t s_data_ready_flag = 0U;

static uint8_t  s_rx_frame[BLE_FRAME_MAX_LEN];
static uint8_t  s_rx_pos = 0U;
static uint8_t  s_expected_len = 0U;
static uint8_t  s_ble_enabled = 0U;
static BleRxCallback_t s_rx_cb = NULL;

static uint8_t ble_crc8(const uint8_t *data, uint8_t len)
{
    uint8_t crc = 0x00U;
    uint8_t i, b;
    for (i = 0U; i < len; i++)
    {
        crc ^= data[i];
        for (b = 0U; b < 8U; b++)
        {
            crc = (crc & 0x80U) ? (uint8_t)((crc << 1) ^ 0x07U) : (uint8_t)(crc << 1);
        }
    }
    return crc;
}

void BSP_BLE_Init(BleRxCallback_t cb)
{
    s_rx_cb = cb;
    s_rx_head = 0U;
    s_rx_tail = 0U;
    s_rx_pos = 0U;
    s_expected_len = 0U;
    s_data_ready_flag = 0U;

    HAL_GPIO_WritePin(BLE_MOD_GPIO_Port, BLE_MOD_Pin, GPIO_PIN_SET); /* Transparent mode */
    HAL_GPIO_WritePin(BLE_WKP_GPIO_Port, BLE_WKP_Pin, GPIO_PIN_SET);
    BSP_BLE_Reset();
    HAL_UART_Receive_IT(&huart1, &s_rx_byte_it, 1U);
}

void BSP_BLE_Reset(void)
{
    HAL_GPIO_WritePin(BLE_RST_GPIO_Port, BLE_RST_Pin, GPIO_PIN_RESET);
    HAL_Delay(10U);
    HAL_GPIO_WritePin(BLE_RST_GPIO_Port, BLE_RST_Pin, GPIO_PIN_SET);
}

void BSP_BLE_SetEnabled(uint8_t enable)
{
    s_ble_enabled = enable ? 1U : 0U;
    HAL_GPIO_WritePin(BLE_WKP_GPIO_Port, BLE_WKP_Pin, s_ble_enabled ? GPIO_PIN_RESET : GPIO_PIN_SET);
}

uint8_t BSP_BLE_IsConnected(void)
{
    /* E104-BT5005A LINK pin outputs LOW when BLE connection is active */
    return (HAL_GPIO_ReadPin(BLE_LINK_GPIO_Port, BLE_LINK_Pin) == GPIO_PIN_RESET) ? 1U : 0U;
}

void BSP_BLE_OnUartRxByte(uint8_t byte)
{
    uint16_t next = (uint16_t)((s_rx_head + 1U) % BLE_RX_RING_SIZE);
    if (next != s_rx_tail)
    {
        s_rx_ring[s_rx_head] = byte;
        s_rx_head = next;
    }
    HAL_UART_Receive_IT(&huart1, &s_rx_byte_it, 1U);
}

void BSP_BLE_OnDataReadyExti(void)
{
    s_data_ready_flag = 1U;
}

void BSP_BLE_Poll(void)
{
    (void)s_data_ready_flag;
    s_data_ready_flag = 0U;

    while (s_rx_tail != s_rx_head)
    {
        uint8_t b = s_rx_ring[s_rx_tail];
        s_rx_tail = (uint16_t)((s_rx_tail + 1U) % BLE_RX_RING_SIZE);

        if (s_rx_pos == 0U)
        {
            if (b == BLE_FRAME_SOF0) s_rx_frame[s_rx_pos++] = b;
            continue;
        }
        if (s_rx_pos == 1U)
        {
            if (b == BLE_FRAME_SOF1) s_rx_frame[s_rx_pos++] = b;
            else s_rx_pos = (b == BLE_FRAME_SOF0) ? 1U : 0U;
            continue;
        }
        if (s_rx_pos == 2U)
        {
            /* LEN = cmd + payload bytes (1..25) */
            if (b >= 1U && b <= 25U)
            {
                s_expected_len = (uint8_t)(b + 5U); /* SOF0,SOF1,LEN + (LEN) + CRC + EOF */
                s_rx_frame[s_rx_pos++] = b;
            }
            else
            {
                s_rx_pos = 0U;
            }
            continue;
        }

        if (s_rx_pos < BLE_FRAME_MAX_LEN)
        {
            s_rx_frame[s_rx_pos++] = b;
        }
        else
        {
            s_rx_pos = 0U;
            continue;
        }

        if (s_rx_pos >= s_expected_len)
        {
            uint8_t len_field = s_rx_frame[2];
            uint8_t calc_crc = ble_crc8(&s_rx_frame[2], (uint8_t)(1U + len_field));
            uint8_t rx_crc   = s_rx_frame[3U + len_field];
            uint8_t rx_eof   = s_rx_frame[4U + len_field];

            if (rx_eof == BLE_FRAME_EOF && calc_crc == rx_crc && s_rx_cb != NULL)
            {
                BleRxCommand_t cmd;
                memset(&cmd, 0, sizeof(cmd));
                cmd.cmd_id = s_rx_frame[3];
                cmd.payload_len = (len_field > 1U) ? (uint8_t)(len_field - 1U) : 0U;
                if (cmd.payload_len > 0U)
                {
                    memcpy(cmd.payload, &s_rx_frame[4], cmd.payload_len);
                }
                s_rx_cb(&cmd);
            }
            s_rx_pos = 0U;
        }
    }
}

void BSP_BLE_SendTelemetry(const BleTelemetry_t *t)
{
    uint8_t frame[24];
    uint8_t idx = 0U;

    if (t == NULL || !s_ble_enabled) return;

    frame[idx++] = BLE_FRAME_SOF0;
    frame[idx++] = BLE_FRAME_SOF1;
    frame[idx++] = 16U; /* LEN: 1(cmd) + 15(payload) */
    frame[idx++] = BLE_CMD_TELEMETRY;
    frame[idx++] = t->breath_mode;
    frame[idx++] = t->stim_mode;
    frame[idx++] = t->stim_freq_hz;
    frame[idx++] = t->stim_level[0];
    frame[idx++] = t->stim_level[1];
    frame[idx++] = t->stim_level[2];
    frame[idx++] = t->timer_min;
    frame[idx++] = (uint8_t)(t->elapsed_sec >> 8);
    frame[idx++] = (uint8_t)(t->elapsed_sec & 0xFFU);
    frame[idx++] = (uint8_t)(t->remain_sec >> 8);
    frame[idx++] = (uint8_t)(t->remain_sec & 0xFFU);
    frame[idx++] = t->guide_bpm;
    frame[idx++] = t->real_cbpm;
    frame[idx++] = t->elec_drop_mask;
    frame[idx++] = (uint8_t)((t->running ? 1U : 0U) | (t->paused ? 2U : 0U));
    frame[idx]   = ble_crc8(&frame[2], 17U);
    idx++;
    frame[idx++] = BLE_FRAME_EOF;

    HAL_UART_Transmit(&huart1, frame, idx, 50U);
}

