409: static void sort_paired_data(float* x, float* y, int n)
410: {
411:     int i, j;
412:     for (i = 0; i < n - 1; i++)
413:     {
414:         for (j = 0; j < n - i - 1; j++)
415:         {
416:             if (y[j] > y[j+1])
417:             {
418:                 // 交换y值
419:                 float temp_y = y[j];
420:                 y[j] = y[j+1];
421:                 y[j+1] = temp_y;
422: 
423:                 // 同步交换x值
424:                 float temp_x = x[j];
425:                 x[j] = x[j+1];
426:                 x[j+1] = temp_x;
427:             }
428:         }
429:     }
430: }
