#include "bsp_screen.h"
#include "bsp_audio.h"
#include "bsp_power.h"
#include "therapy_ctrl.h"
#include "cmsis_os.h"

/* ============================================================================
 * ScreenTask: FPM tjc_task.c-style 3-level switch-case frame parser
 *   Frame format from TJC HMI: [0x05] [page] [control] [value] [0xFF 0xFF 0xFF]
 *   plus periodic UI refresh (lung animation 0..100, remain timer, battery).
 * ========================================================================== */

static void Screen_HandleCtrlFrame(uint8_t page, uint8_t control, uint8_t value)
{
    switch (page)
    {
        case SCREEN_PAGE_START: /* 0x00: Main menu */
        {
            switch (control)
            {
                case 0x01U: /* Breath training mode button */
                {
                    switch (value)
                    {
                        case 0x01U:
                            App_Therapy_EnterBreathMenu(0U);
                            break;
                        default:
                            break;
                    }
                    break;
                }
                case 0x02U: /* Electrical stimulation mode button */
                {
                    switch (value)
                    {
                        case 0x01U:
                            App_Therapy_EnterStimMenu();
                            break;
                        default:
                            break;
                    }
                    break;
                }
                case 0x03U: /* Combined (Breath + Stim) mode button */
                {
                    switch (value)
                    {
                        case 0x01U:
                            App_Therapy_EnterBreathMenu(1U);
                            break;
                        default:
                            break;
                    }
                    break;
                }
                default:
                    break;
            }
            break;
        }

        case SCREEN_PAGE_BREATH_SEL: /* 0x01: Breath submode selection */
        {
            switch (control)
            {
                case 0x01U: /* Simple mode */
                {
                    switch (value)
                    {
                        case 0x01U: /* Highlighted */
                            break;
                        case 0x02U: /* Next page confirmed */
                            App_Therapy_SelectBreathMode(BREATH_MODE_SIMPLE);
                            if (g_app.Stim_Mode != STIM_MODE_OFF)
                            {
                                BSP_Audio_PlayVoice(AUDIO_VOICE_SEL_STIM_MODE);
                            }
                            else
                            {
                                BSP_Screen_SetGuideBPM(10U);
                                BSP_Screen_SetSettingsDisplay(g_app.volume, g_app.timer_min, g_app.ble_enabled);
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                }
                case 0x02U: /* Biofeedback mode */
                {
                    switch (value)
                    {
                        case 0x01U: /* Highlighted */
                            break;
                        case 0x02U: /* Next page confirmed */
                            App_Therapy_SelectBreathMode(BREATH_MODE_BIOFEEDBACK);
                            break;
                        default:
                            break;
                    }
                    break;
                }
                case 0x0FU: /* Return to main menu */
                {
                    if (value == 0x01U)
                    {
                        App_Therapy_StopToMenu();
                    }
                    break;
                }
                default:
                    break;
            }
            break;
        }

        case SCREEN_PAGE_STIM_SEL: /* 0x02: Stimulation waveform selection */
        {
            switch (control)
            {
                case 0x01U: /* Continuous wave */
                    if (value == 0x01U) App_Therapy_SelectStimMode(STIM_MODE_CONTINUOUS);
                    break;
                case 0x02U: /* Intermittent wave */
                    if (value == 0x01U) App_Therapy_SelectStimMode(STIM_MODE_INTERMITTENT);
                    break;
                case 0x03U: /* Dense-Disperse wave */
                    if (value == 0x01U) App_Therapy_SelectStimMode(STIM_MODE_DENSE_DISPERSE);
                    break;
                case 0x0FU: /* Return */
                    if (value == 0x01U) App_Therapy_StopToMenu();
                    break;
                default:
                    break;
            }
            if (control >= 0x01U && control <= 0x03U && value == 0x01U)
            {
                BSP_Screen_SetStimParams(g_app.stim_freq_hz, g_app.stim_level);
                BSP_Screen_SetSettingsDisplay(g_app.volume, g_app.timer_min, g_app.ble_enabled);
            }
            break;
        }

        case SCREEN_PAGE_TREAT_RUN: /* 0x03: Treatment ready / running / paused */
        {
            switch (control)
            {
                case 0x01U: /* Start / Pause button */
                    if (value == 0x01U) App_Therapy_StartOrPause();
                    break;
                case 0x02U: /* Return button (blocked while running) */
                    if (value == 0x01U) App_Therapy_StopToMenu();
                    break;
                case 0x03U: /* Settings button (blocked while running) */
                    if (value == 0x01U) App_Therapy_EnterSettings();
                    break;
                case 0x10U: /* Frequency slider/stepper: value = 0..100 Hz */
                    App_Therapy_SetStimFreq(value);
                    break;
                case 0x11U: /* CH1 level: value = 0..10 */
                    App_Therapy_SetStimLevel(0U, value);
                    break;
                case 0x12U: /* CH2 level: value = 0..10 */
                    App_Therapy_SetStimLevel(1U, value);
                    break;
                case 0x13U: /* CH3 level: value = 0..10 */
                    App_Therapy_SetStimLevel(2U, value);
                    break;
                default:
                    break;
            }
            break;
        }

        case SCREEN_PAGE_SETTINGS: /* 0x04: Parameter settings */
        {
            switch (control)
            {
                case 0x01U: /* Volume: value = 0..10 */
                    App_Therapy_SetVolume(value);
                    break;
                case 0x02U: /* Timer: value = 5..30 min */
                    App_Therapy_SetTimerMin(value);
                    break;
                case 0x03U: /* Bluetooth switch: 0=Off, 1=On */
                    App_Therapy_SetBleEnable(value);
                    break;
                case 0x0FU: /* Return from settings */
                    if (value == 0x01U) App_Therapy_ReturnFromSettings();
                    break;
                default:
                    break;
            }
            break;
        }

        case SCREEN_PAGE_END: /* 0x05: Summary screen */
        {
            switch (control)
            {
                case 0x01U: /* Confirm / back to menu */
                    if (value == 0x01U) App_Therapy_StopToMenu();
                    break;
                default:
                    break;
            }
            break;
        }

        default:
            break;
    }
}

static void Screen_HandleTouchFrame(uint8_t page, uint8_t comp_id, uint8_t event)
{
    /* Optional fallback for native TJC 0x65 [page] [comp_id] [event] release frames */
    if (event != 0x00U) return;
    Screen_HandleCtrlFrame(page, comp_id, 0x01U);
}

void ScreenTask(void const *argument)
{
    ScreenFrame_t frame;
    uint32_t tick_cnt = 0U;
    uint8_t  last_lung = 255U;
    uint16_t last_remain_s = 0xFFFFU;
    (void)argument;

    osDelay(50U);

    for (;;)
    {
        /* 1. Drain and parse all complete frames ending with 0xFF 0xFF 0xFF */
        while (BSP_Screen_ReadFrame(&frame))
        {
            switch (frame.header)
            {
                case SCREEN_FRAME_HDR_CTRL: /* 0x05 [page] [control] [value] */
                    if (frame.len >= 4U)
                    {
                        Screen_HandleCtrlFrame(frame.page, frame.control, frame.value);
                    }
                    break;

                case SCREEN_FRAME_HDR_TOUCH: /* 0x65 [page] [comp] [event] */
                    if (frame.len >= 4U)
                    {
                        Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
                    }
                    break;

                default:
                    break;
            }
        }

        /* 2. Periodic UI refresh: lung animation 0..100 & remaining time */
        if (g_app.running && !g_app.paused)
        {
            if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
            {
                last_lung = g_app.lung_pct;
                BSP_Screen_SetLungFill(last_lung);
            }

            if ((tick_cnt % 10U) == 0U) /* Every 200 ms */
            {
                uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
                uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
                uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
                if (rem_s != last_remain_s)
                {
                    last_remain_s = rem_s;
                    BSP_Screen_SetRemainTimeSec(rem_s);
                }
            }
        }
        else
        {
            last_lung = 255U;
            last_remain_s = 0xFFFFU;
        }

        /* 3. Refresh battery status every 10 s */
        if ((tick_cnt % 500U) == 0U)
        {
            BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
        }

        tick_cnt++;
        osDelay(20U);
    }
}

