44: void intToStr(int num, char* str) {
45:     int i = 0;
46:     int isNegative = 0;
47: 
48:     // 处理负数
49:     if (num < 0) {
50:         isNegative = 1;
51:         num = -num;
52:     }
53: 
54:     // 提取每一位数字
55:     do {
56:         str[i++] = (num % 10) + '0';
57:         num /= 10;
58:     } while (num);
59: 
60:     // 如果是负数，添加负号
61:     if (isNegative) {
62:         str[i++] = '-';
63:     }
64: 
65:     // 添加字符串终止符
66:     str[i] = '\0';
67: 
68:     // 反转字符串
69:     int start = 0;
70:     int end = i - 1;
71:     while (start < end) {
72:         char temp = str[start];
73:         str[start] = str[end];
74:         str[end] = temp;
75:         start++;
76:         end--;
77:     }
78:     return ;
79: }
