296: /**
297:  * @brief  串口屏 FreeRTOS 任务入口函数（周期 20 ms）
298:  * @note   1. 持续从环形缓冲区提取完整帧并进入三级 switch-case 分发
299:  *         2. 治疗运行期按需节流刷新肺部动画（0~100）与剩余倒计时
300:  *         3. 每 10 秒刷新一次电池电量图标
301:  * @param  argument: FreeRTOS 任务参数（未使用）
302:  * @retval 无
303:  */
304: void ScreenTask(void const *argument)
305: {
306:     ScreenFrame_t frame;
307:     uint32_t tick_cnt = 0U;
308:     uint8_t  last_lung = 255U;      /* 上次已发送的肺部进度，用于变化检测节流 */
309:     uint16_t last_remain_s = 0xFFFFU;
310:     (void)argument;
311: 
312:     osDelay(50U);
313: 
314:     for (;;)
315:     {
316:         /* 1. 排空并解析所有以 0xFF 0xFF 0xFF 结尾的完整上行数据帧 */
317:         while (BSP_Screen_ReadFrame(&frame))
318:         {
319:             if (frame.header == SCREEN_FRAME_HDR_CTRL || frame.header == SCREEN_FRAME_HDR_CUSTOM)
320:             {
321:                 if (frame.len >= 3U)
322:                 {
323:                     Screen_HandleCtrlFrame(&frame);
324:                 }
325:             }
326:             else if (frame.header == SCREEN_FRAME_HDR_TOUCH) /* 淘晶驰原生触摸帧兜底：0x65 [page] [comp] [event] */
327:             {
328:                 if (frame.len >= 4U)
329:                 {
330:                     Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
331:                 }
332:             }
333:         }
334: 
335:         /* 2. 治疗运行中定时刷新肺部动画与剩余时间（值变化时才发送，降低串口负载） */
336:         if (g_app.running && !g_app.paused)
337:         {
338:             if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
339:             {
340:                 last_lung = g_app.lung_pct;
341:                 BSP_Screen_SetLungFill(last_lung);
342:             }
343: 
344:             if ((tick_cnt % 10U) == 0U) /* 每 200 ms 检查一次倒计时秒数变化 */
345:             {
346:                 uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
347:                 uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
348:                 uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
349:                 if (rem_s != last_remain_s)
350:                 {
351:                     last_remain_s = rem_s;
352:                     BSP_Screen_SetRemainTimeSec(rem_s);
353:                 }
354:             }
355:         }
356:         else
357:         {
358:             last_lung = 255U;
359:             last_remain_s = 0xFFFFU;
360:         }
361: 
362:         /* 3. 每 10 s（500 * 20 ms）刷新一次电量显示 */
363:         if ((tick_cnt % 500U) == 0U)
364:         {
365:             BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
366:         }
367: 
368:         tick_cnt++;
369:         osDelay(20U);
370:     }
371: }

