352: /**
353:  * @brief  串口屏 FreeRTOS 任务入口函数（周期 20 ms）
354:  * @note   1. 持续从环形缓冲区提取完整帧并进入三级 switch-case 分发
355:  *         2. 治疗运行期按需节流刷新肺部动画（0~100）与剩余倒计时
356:  *         3. 每 10 秒刷新一次电池电量图标
357:  * @param  argument: FreeRTOS 任务参数（未使用）
358:  * @retval 无
359:  */
360: void ScreenTask(void const *argument)
361: {
362:     ScreenFrame_t frame;
363:     uint32_t tick_cnt = 0U;
364:     uint8_t  last_lung = 255U;      /* 上次已发送的肺部进度，用于变化检测节流 */
365:     uint16_t last_remain_s = 0xFFFFU;
366:     (void)argument;
367: 
368:     osDelay(50U);
369: 
370:     /* 启动初期显式关闭屏幕休眠与自动休眠定时器，确保屏幕始终常亮不熄屏 */
371:     BSP_Screen_SendRawCmd("sleep=0");
372:     BSP_Screen_SendRawCmd("usleep=0");
373: 
374:     for (;;)
375:     {
376:         /* 1. 排空并解析所有以 0xFF 0xFF 0xFF 结尾的完整上行数据帧 */
377:         while (BSP_Screen_ReadFrame(&frame))
378:         {
379:             if (frame.header == SCREEN_FRAME_HDR_CTRL || frame.header == SCREEN_FRAME_HDR_CUSTOM)
380:             {
381:                 if (frame.len >= 3U)
382:                 {
383:                     Screen_HandleCtrlFrame(&frame);
384:                 }
385:             }
386:             else if (frame.header == SCREEN_FRAME_HDR_TOUCH) /* 淘晶驰原生触摸帧兜底：0x65 [page] [comp] [event] */
387:             {
388:                 if (frame.len >= 4U)
389:                 {
390:                     Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
391:                 }
392:             }
393:         }
394: 
395:         /* 2. 治疗运行中定时刷新肺部动画与剩余时间（值变化时才发送，降低串口负载） */
396:         if (g_app.running && !g_app.paused)
397:         {
398:             if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
399:             {
400:                 last_lung = g_app.lung_pct;
401:                 BSP_Screen_SetLungFill(last_lung);
402:             }
403: 
404:             if ((tick_cnt % 10U) == 0U) /* 每 200 ms 检查一次倒计时秒数变化 */
405:             {
406:                 uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
407:                 uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
408:                 uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
409:                 if (rem_s != last_remain_s)
410:                 {
411:                     last_remain_s = rem_s;
412:                     BSP_Screen_SetRemainTimeSec(rem_s);
413:                 }
414:             }
415:         }
416:         else
417:         {
418:             last_lung = 255U;
419:             last_remain_s = 0xFFFFU;
420:         }
421: 
422:         /* 3. 每 10 s（500 * 20 ms）刷新一次电量显示 */
423:         if ((tick_cnt % 500U) == 0U)
424:         {
425:             BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
426:         }
427: 
428:         tick_cnt++;
429:         osDelay(20U);
430:     }
431: }

