20: static uint8_t ble_crc8(const uint8_t *data, uint8_t len)
21: {
22:     uint8_t crc = 0x00U;
23:     uint8_t i, b;
24:     for (i = 0U; i < len; i++)
25:     {
26:         crc ^= data[i];
27:         for (b = 0U; b < 8U; b++)
28:         {
29:             crc = (crc & 0x80U) ? (uint8_t)((crc << 1) ^ 0x07U) : (uint8_t)(crc << 1);
30:         }
31:     }
32:     return crc;
33: }
