85: void BSP_BLE_Poll(void)
86: {
87:     (void)s_data_ready_flag;
88:     s_data_ready_flag = 0U;
89: 
90:     while (s_rx_tail != s_rx_head)
91:     {
92:         uint8_t b = s_rx_ring[s_rx_tail];
93:         s_rx_tail = (uint16_t)((s_rx_tail + 1U) % BLE_RX_RING_SIZE);
94: 
95:         if (s_rx_pos == 0U)
96:         {
97:             if (b == BLE_FRAME_SOF0) s_rx_frame[s_rx_pos++] = b;
98:             continue;
99:         }
100:         if (s_rx_pos == 1U)
101:         {
102:             if (b == BLE_FRAME_SOF1) s_rx_frame[s_rx_pos++] = b;
103:             else s_rx_pos = (b == BLE_FRAME_SOF0) ? 1U : 0U;
104:             continue;
105:         }
106:         if (s_rx_pos == 2U)
107:         {
108:             /* LEN = cmd + payload bytes (1..25) */
109:             if (b >= 1U && b <= 25U)
110:             {
111:                 s_expected_len = (uint8_t)(b + 5U); /* SOF0,SOF1,LEN + (LEN) + CRC + EOF */
112:                 s_rx_frame[s_rx_pos++] = b;
113:             }
114:             else
115:             {
116:                 s_rx_pos = 0U;
117:             }
118:             continue;
119:         }
120: 
121:         if (s_rx_pos < BLE_FRAME_MAX_LEN)
122:         {
123:             s_rx_frame[s_rx_pos++] = b;
124:         }
125:         else
126:         {
127:             s_rx_pos = 0U;
128:             continue;
129:         }
130: 
131:         if (s_rx_pos >= s_expected_len)
132:         {
133:             uint8_t len_field = s_rx_frame[2];
134:             uint8_t calc_crc = ble_crc8(&s_rx_frame[2], (uint8_t)(1U + len_field));
135:             uint8_t rx_crc   = s_rx_frame[3U + len_field];
136:             uint8_t rx_eof   = s_rx_frame[4U + len_field];
137: 
138:             if (rx_eof == BLE_FRAME_EOF && calc_crc == rx_crc && s_rx_cb != NULL)
139:             {
140:                 BleRxCommand_t cmd;
141:                 memset(&cmd, 0, sizeof(cmd));
142:                 cmd.cmd_id = s_rx_frame[3];
143:                 cmd.payload_len = (len_field > 1U) ? (uint8_t)(len_field - 1U) : 0U;
144:                 if (cmd.payload_len > 0U)
145:                 {
146:                     memcpy(cmd.payload, &s_rx_frame[4], cmd.payload_len);
147:                 }
148:                 s_rx_cb(&cmd);
149:             }
150:             s_rx_pos = 0U;
151:         }
152:     }
153: }
