155: void BSP_BLE_SendTelemetry(const BleTelemetry_t *t)
156: {
157:     uint8_t frame[24];
158:     uint8_t idx = 0U;
159: 
160:     if (t == NULL || !s_ble_enabled) return;
161: 
162:     frame[idx++] = BLE_FRAME_SOF0;
163:     frame[idx++] = BLE_FRAME_SOF1;
164:     frame[idx++] = 16U; /* LEN: 1(cmd) + 15(payload) */
165:     frame[idx++] = BLE_CMD_TELEMETRY;
166:     frame[idx++] = t->breath_mode;
167:     frame[idx++] = t->stim_mode;
168:     frame[idx++] = t->stim_freq_hz;
169:     frame[idx++] = t->stim_level[0];
170:     frame[idx++] = t->stim_level[1];
171:     frame[idx++] = t->stim_level[2];
172:     frame[idx++] = t->timer_min;
173:     frame[idx++] = (uint8_t)(t->elapsed_sec >> 8);
174:     frame[idx++] = (uint8_t)(t->elapsed_sec & 0xFFU);
175:     frame[idx++] = (uint8_t)(t->remain_sec >> 8);
176:     frame[idx++] = (uint8_t)(t->remain_sec & 0xFFU);
177:     frame[idx++] = t->guide_bpm;
178:     frame[idx++] = t->real_cbpm;
179:     frame[idx++] = t->elec_drop_mask;
180:     frame[idx++] = (uint8_t)((t->running ? 1U : 0U) | (t->paused ? 2U : 0U));
181:     frame[idx]   = ble_crc8(&frame[2], 17U);
182:     idx++;
183:     frame[idx++] = BLE_FRAME_EOF;
184: 
185:     HAL_UART_Transmit(&huart1, frame, idx, 50U);
186: }

